[Form]
public class METItemDetailsInquiryWorkspace extends FormRun implements SysIFilterProvider,METItemInquiryFilerProvider
{
    private SysFilterChangeEvent filterChangeEvent;
    private boolean isISPUser;
}

/// <summary>
/// Refreshes all tile controls in the workspace by calling their getData() methods.
/// Use this to update the displayed data after filter changes.
/// </summary>
public void refreshTiles()
{
    // Call the getData() method for each tile control to refresh their data
    METProductReceiptInfoTileLast30days.getData();
    METOverDuePurchaseOrdersTile.getData();
    METSalesOrderShipmentsTile.getData();
    METOverDueSOShipmentsTile.getData();
    // Add other tile controls as needed
}

/// <summary>
/// Gets the current ItemId filter value from the ItemIdFilter control.
/// </summary>
/// <returns>The ItemId value entered in the filter control.</returns>

public METItemNumber parmItemIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(METItemNumber));

}

/// <summary>
/// Gets the current InventLocationId filter value from the InventLocationIdFilter control.
/// </summary>
/// <returns>The InventLocationId value entered in the filter control.</returns>

public METInventLocationId parminventoryLocationIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(METInventLocationId));

}

/// <summary>
/// Parameter method to get the ItemId from the ItemId filter control.
/// </summary>
/// <returns>The ItemId value entered in the filter control.</returns>
public METItemNumber parmItemId()
{
    return ItemIDFilter.valueStr();
}

/// <summary>
/// Parameter method to get the InventLocationId from the InventLocationId filter control.
/// </summary>
/// <returns>The InventLocationId value entered in the filter control.</returns>
public METInventLocationId parminventoryLocationId()
{
    return InventLocationIdFilter.valueStr();
}

/// <summary>
/// Parameter method to construct the SysIFilter based on the current filter control values.
/// </summary>
/// <returns>SysFilter</returns>
public SysIFilter parmFilter()
{
    SysIFilter                      filter              = SysFilterFactory::createEmptyFilter();
    SysFilterValueResolutionMethod  resolutionMethod    = SysFilterValueResolutionMethod::All;

    if (this.parmItemId() != '')
    {
        SysIFilterValue itemFilter = SysFilterValueFactory::createFilterValueForString(this.parmItemId(), extendedTypeNum(METItemNumber));
        filter.addItem(itemFilter, SysFilterOperator::Equal, SysFilterValueResolutionMethod::None);
    }

    if (this.parminventoryLocationId() != '')
    {
        SysIFilterValue wareHouseFilter = SysFilterValueFactory::createFilterValueForString(this.parminventoryLocationId(), extendedTypeNum(METInventLocationId));
        filter.addItem(wareHouseFilter, SysFilterOperator::Equal, SysFilterValueResolutionMethod::None);
    }

    return filter;
}

/// <summary>
/// Returns the SysFilterChangeEvent for the ItemId and InventLocationId filter controls.
/// Used to track filter changes and trigger updates.
/// </summary>
/// <returns>The SysFilterChangeEvent instance for the filter controls.</returns>

public SysFilterChangeEvent parmChangeEvent()
{
    filterChangeEvent = SysFilterChangeEvent::newFromFormControl(ItemIDFilter);
    filterChangeEvent.registerFormControl(InventLocationIdFilter);
    return filterChangeEvent;

}

/// <summary>
/// Initializes the filter controls and retrieves their last saved values.
/// </summary>
public void init()
{
    InventParameters inventParameters = InventParameters::find();

    super();

    PowerBIWebsiteHostControl.url(inventParameters.METItemInquiryPBIReportURL);
    SysFilterLastValueHelper::getLastValue(ItemIdFilter);
    SysFilterLastValueHelper::getLastValue(InventLocationIdFilter);

    filterChangeEvent = SysFilterChangeEvent::newFromFormControl(ItemIdFilter);
    filterChangeEvent.registerFormControl(InventLocationIdFilter);

    isISPUser = METisISPUser();

    METOverDueSOShipmentsTile.visible(!isISPUser);
    METSalesOrderShipmentsTile.visible(!isISPUser);
}

/// <summary>
/// Closes the form and saves the last values of the filter controls.
/// </summary>
public void close()
{
    // Save the last value of the ItemId filter control
    super();
    SysFilterLastValueHelper::saveLastValue(ItemIdFilter);
    SysFilterLastValueHelper::saveLastValue(InventLocationIdFilter);

}

/// <summary>
/// Modified method to refresh tiles and reload data when the ItemId filter changes.
/// </summary>
/// <returns>True/False</returns>
public boolean modified()
{
    boolean ret;    
    ret = super();

    element.refreshTiles();
    element.reload();
    return ret;
}

/// <summary>
/// Lookup method to provide a lookup for ItemId field.
/// </summary>
public void lookup()
{
    Query                   query = new Query();
    QueryBuildRange         queryBuildRange;
    QueryBuildDataSource    qbdsInventTable, qbdsInventTableExpanded;

    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventTableExpanded), this);

    sysTableLookup.addLookupField(fieldNum(InventTableExpanded, ItemId));
    sysTableLookup.addLookupField(fieldNum(InventTableExpanded, NameAlias));
    sysTableLookup.addLookupField(fieldNum(InventTableExpanded, ProductName));
    sysTableLookup.addLookupField(fieldNum(InventTableExpanded, ItemGroupId));
    sysTableLookup.addLookupField(fieldNum(InventTableExpanded, ItemType));

    qbdsInventTableExpanded = query.addDataSource(tableNum(InventTableExpanded));

    qbdsInventTableExpanded.relations(true);

    sysTableLookup.parmQuery(query);

    sysTableLookup.performFormLookup();
}

/// <summary>
/// Modified method to refresh tiles and reload data when the InventLocationId filter changes.
/// </summary>
/// <returns>True/Fale</returns>
public boolean modified()
{
    boolean ret;            

    ret = super();
    element.refreshTiles();
    element.reload();

    return ret;
}

/// <summary>
/// Lookup method to provide a lookup for InventLocationId field.
/// </summary>
public void lookup()
{
    Query                   query = new Query();
    QueryBuildRange         queryBuildRange;
    QueryBuildDataSource    queryBuildDataSource;
    QueryBuildDataSource    qbdsUserWarehouse;

    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), this);

    sysTableLookup.addLookupField(fieldNum(InventLocation, InventLocationId));
    sysTableLookup.addLookupField(fieldNum(InventLocation, Name));
    sysTableLookup.addLookupField(fieldNum(InventLocation, InventSiteId));
    queryBuildDataSource = query.addDataSource(tableNum(InventLocation));

    if (METApplyWarehouseRestrictionForISPUsers())
    {
        qbdsUserWarehouse = queryBuildDataSource.addDataSource(tableNum(METAllowedWarehousesForISPUsers));
        qbdsUserWarehouse.joinMode(JoinMode::InnerJoin);
        qbdsUserWarehouse.addRange(fieldnum(METAllowedWarehousesForISPUsers, UserId)).value(curUserId());

        qbdsUserWarehouse.addLink(fieldNum(InventLocation, InventLocationId), fieldNum(METAllowedWarehousesForISPUsers, InventLocationId));
    }

    sysTableLookup.parmQuery(query);

    sysTableLookup.performFormLookup();
}

/// <summary>
/// Gets the data for the Product Receipt Info tile for the last 30 days.
/// </summary>
/// <returns>TileButtonControlData</returns>
public TileButtonControlData getData()
{
    TileButtonControlData   ret;
    VendPackingSlipJour     packingSlipJour;
    VendPackingSlipTrans    packingSlipTrans;
    TransDate               currentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    PurchTable              purchTable;
    TransDate               lastMonthDate = currentDate-30;
    PurchLine               purchLine;

    ret = super();

    if (element.parminventoryLocationId() == '')
    {
        select count(RecId) from packingSlipJour
            index hint SDHeaderIdx
            where packingSlipJour.DeliveryDate >= lastMonthDate
               && packingSlipJour.DeliveryDate <= currentDate
            exists join packingSlipTrans
            where packingSlipTrans.VendPackingSlipJour == packingSlipJour.RecId
                && packingSlipTrans.ItemId == element.parmItemId()
            exists join forUpdate purchTable
            where purchTable.PurchId == packingSlipJour.PurchId;
    }
    else
    {
        select count(RecId) from packingSlipJour
            index hint SDHeaderIdx
            where packingSlipJour.DeliveryDate >= lastMonthDate
                && packingSlipJour.DeliveryDate <= currentDate
            exists join packingSlipTrans
            where packingSlipTrans.VendPackingSlipJour == packingSlipJour.RecId
                && packingSlipTrans.ItemId == element.parmItemId()
            exists join forUpdate purchTable
            where purchTable.PurchId == packingSlipJour.PurchId
                && purchTable.InventLocationId ==  element.parminventoryLocationId();
    }
    ret.strTileData(int642Str(packingSlipJour.RecId));
    return ret;
}

