/// <summary>
/// Gets the data for the Overdue Purchase Orders tile.
/// </summary>
/// <returns>TileButtonControlData</returns>
public TileButtonControlData getData()
{
    TransDate                       currentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    TileButtonControlData           ret;
    PurchLineBackOrderWorkspace     backOrder;
    InventDim                       inventDim;
    EcoResCategory                  category;
    PurchTable                      purchTable;

    ret = super();

    if (element.parminventoryLocationId() == '')
    {              
        select count(RecId) from backOrder
            where backOrder.ExpectedDate <= currentDate
                && backOrder.RemainPurchPhysical != 0
                && backOrder.ItemId == element.parmItemId()
            join forUpdate inventDim
            where inventDim.inventDimId == backOrder.InventDimId
            outer join forUpdate category
            where category.RecId == backOrder.ProcurementCategory
            join forUpdate purchTable
            where purchTable.PurchId == backOrder.PurchId;

    }
    else
    {
        select count(RecId) from backOrder
            where backOrder.ExpectedDate <= currentDate
                && backOrder.RemainPurchPhysical != 0
                && backOrder.ItemId == element.parmItemId()
            join forUpdate inventDim
            where inventDim.inventDimId == backOrder.InventDimId
            outer join forUpdate category
            where category.RecId == backOrder.ProcurementCategory
            join forUpdate purchTable
            where purchTable.PurchId == backOrder.PurchId
                && purchTable.InventLocationId == element.parminventoryLocationId();
    }
    ret.strTileData(int642Str(backOrder.RecId));
    return ret;
}

