/// <summary>
/// Gets the data for the Overdue Sales Order Shipments tile.
/// </summary>
/// <returns>TileButtonControlData</returns>
public TileButtonControlData getData()
{
    TransDate                       currentDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    TileButtonControlData           ret;
    METSalesOrderShipmentLoadHeader header;
    METSalesOrderShipmentLoadLines  lines;
    TransDate                       prev14Days = currentDate-14;

    ret = super();

    if (element.parminventoryLocationId() == '')
    {
        select count(RecId) from header
            where header.TransactionType == METOrderTransactionType::SalesOrder
                && header.ShipmentStatus == METShipmentStatus::Open
                && header.ConfirmedShipDate < currentDate
            join lines
            where lines.ShipmentId == header.ShipmentId
                && lines.ItemId == element.parmItemId();

    }
    else
    {
        select count(RecId) from header
            where header.TransactionType == METOrderTransactionType::SalesOrder
               && header.ShipmentStatus == METShipmentStatus::Open
               && header.Warehouse == element.parminventoryLocationId()
               && header.ConfirmedShipDate < currentDate
            join lines
            where lines.ShipmentId == header.ShipmentId
               && lines.ItemId == element.parmItemId();

    }

    ret.strTileData(int642Str(header.RecId));
    return ret;

}

